def find_index_for_arithmetic_progression(n, b):
    if n == 2:
        return 1  # Any single element can be removed to form an arithmetic progression

    b.sort()
    differences = [b[i] - b[i - 1] for i in range(1, n)]

    # Check if the entire sequence is already an arithmetic progression
    if differences.count(differences[0]) == n - 1:
        return 1  # Removing any element will still form an arithmetic progression

    # Try removing each element and check if the remaining form an arithmetic progression
    for i in range(n):
        if i == 0:
            new_diff = b[1] - b[2]
            if differences[1:] == [new_diff] * (n - 2):
                return 1
        elif i == n - 1:
            new_diff = b[n - 2] - b[n - 3]
            if differences[:-1] == [new_diff] * (n - 2):
                return n
        else:
            new_diff1 = b[i] - b[i + 1]
            new_diff2 = b[i + 1] - b[i + 2]
            if new_diff1 == new_diff2:
                if differences[:i] == [new_diff1] * i and differences[i + 1:] == [new_diff1] * (n - i - 2):
                    return i + 1

    return -1

